with base as (select *, length(country) as country_length, coalesce(city, 'DIRECT') as resolved_city from suppliers where city is not null), metrics as (select *, lead(country_length) over w_ordered as next_country_length, lag(rating) over w_ordered as prev_rating, lead(rating) over w_ordered as next_rating, row_number() over w_ordered as seq_no from base where country = 'DE' window w_ordered as (partition by city order by rating, id)), valid as (select *, round(next_rating, 2) as next_rating_rounded from metrics where seq_no <> 5), eligible as (select s.* from valid s where exists (select 1 from products ch where ch.supplier_id = s.id and array_contains(ch.tags, 'eco'))), kept as (select s.* from eligible s where not exists (select 1 from products ch where ch.supplier_id = s.id and ch.cost between 230 and 690)), with_last as (select s.*, x.product_stock_qty, x.product_launch_date from kept s left join lateral (select c.stock_qty as product_stock_qty, c.launch_date as product_launch_date from products c where c.supplier_id = s.id order by c.stock_qty desc, c.id desc limit 1) x on true), kept_suppliers as (select s.* from with_last s where not exists (select 1 from products c where c.supplier_id = s.id and c.launch_date >= s.product_launch_date)) select case when prev_rating >= 4.3 then 'LARGE' else 'SMALL' end as prev_rating_tier, date_trunc('year', product_launch_date) as year_start, approx_percentile(country_length, 0.5) as country_length_p50, sum(next_rating) filter (where city = 'Chiang Mai') as chiang_mai_total_next_rating, percentile_approx(next_country_length, array(0.25, 0.5, 0.75)) as next_country_length_quartiles from kept_suppliers group by case when prev_rating >= 4.3 then 'LARGE' else 'SMALL' end, date_trunc('year', product_launch_date) order by chiang_mai_total_next_rating desc nulls first
